mapper.select:
select from ai_knowledge_document
knowledge_base_id = #{knowledgeBaseId}
and (name like concat('%', #{keyword}, '%') or code like concat('%', #{keyword}, '%'))
and status = #{status}
order by updated_at desc, id desc

select 
from ai_knowledge_document
where id = #{id}
  and knowledge_base_id = #{knowledgeBaseId}

select 
from ai_knowledge_document
where knowledge_base_id = #{knowledgeBaseId}
  and code = #{code}

select 
from ai_knowledge_document
where knowledge_base_id = #{knowledgeBaseId}
  and name = #{name}

mapper.insert:
insert into ai_knowledge_document(
    knowledge_base_id, knowledge_base_code, name, code, object_key, file_type, chunk_strategy, file_size,
    status, chunk_count, version, last_error_message
)
values(
    #{knowledgeBaseId}, #{knowledgeBaseCode}, #{name}, #{code}, #{objectKey}, #{fileType}, #{chunkStrategy}, #{fileSize},
    #{status}, #{chunkCount}, #{version}, #{lastErrorMessage}
)

mapper.update:
update ai_knowledge_document
set status = 'READY',
    chunk_count = #{chunkCount},
    last_error_message = null
where id = #{id}
  and version = #{version}

update ai_knowledge_document
set status = 'FAILED',
    chunk_count = 0,
    last_error_message = #{errorMessage}
where id = #{id}
  and version = #{version}
